CREATE TABLE inhf (LIKE inhx INCLUDING DEFAULTS INCLUDING CONSTRAINTS);
CREATE TABLE cmpart(f1 text COMPRESSION lz4) PARTITION BY HASH(f1);
CREATE TABLE idxpart0 PARTITION OF idxpart (i) FOR VALUES WITH (MODULUS 2, REMAINDER 0);
-- The regress file includes this GENERATED BY DEFAULT error case explicitly.
CREATE TABLE gtest_err_8 (a int PRIMARY KEY, b int GENERATED BY DEFAULT AS (a * 2) STORED);
CREATE TABLE cmdata(f1 text COMPRESSION pglz);
CREATE TABLE test_storage (a text, c text STORAGE plain);
CREATE TABLE as_select1 AS EXECUTE select1;
CREATE TABLE t (c) AS VALUES ('bar'::text);
CREATE TABLE selinto_schema.tbl_withdata2 (a) AS SELECT generate_series(1,3) WITH DATA;
CREATE TABLE selinto_schema.tbl_withoutdata (a) AS SELECT generate_series(1,3) WITH NO DATA;
CREATE TEMP TABLE temptest(col) ON COMMIT DELETE ROWS AS SELECT 1;
CREATE TEMP TABLE withoutoid() WITHOUT OIDS;
-- The old oids storage option is parsed, then rejected semantically.
CREATE TABLE withoid() WITH (oids);
CREATE TABLE UNIQUE_TBL (i int UNIQUE NULLS NOT DISTINCT, t text);
CREATE TABLE FKTABLE (tid int, id int, foo int, FOREIGN KEY (tid, id) REFERENCES PKTABLE ON DELETE SET NULL (foo));
CREATE TABLE nv_parent (d date, CHECK (false) NO INHERIT NOT VALID);
CREATE TYPE myvarchar (input = myvarcharin, output = myvarcharout, alignment = integer, storage = main);
CREATE DOMAIN domainint4 int4;
CREATE FUNCTION dup (f1 anyelement, f2 OUT anyelement, f3 OUT anyarray) RETURNS anyelement LANGUAGE sql AS 'select $1';
CREATE FUNCTION dup (f1 anyelement, f2 OUT anyelement, f3 OUT anyarray) AS 'select $1, array[$1,$1]' LANGUAGE sql;
CREATE MATERIALIZED VIEW heapmv USING heap AS SELECT * FROM heaptable;
CREATE POLICY coll_p ON coll_t USING (c < ('foo'::text COLLATE "C"));
CREATE ROLE regress_noiseword SYSID 12345;
CREATE USER regress_rls_bob NOLOGIN;
CREATE SCHEMA AUTHORIZATION CURRENT_ROLE CREATE SEQUENCE schema_not_existing.seq;
CREATE UNIQUE INDEX concur_exprs_index_expr ON concur_exprs_tab ((c1::text COLLATE "C"));
CREATE UNIQUE INDEX concur_exprs_index_pred ON concur_exprs_tab (c1) WHERE (c1::text > 500000000::text COLLATE "C");
CREATE INDEX wowidx1 ON test_tsvector USING gist (a tsvector_ops);
CREATE VIEW tt26v AS SELECT x + y + z AS c1;
CREATE VIEW bv1 WITH (security_barrier) AS SELECT * FROM b1 WHERE a > 0 WITH CHECK OPTION;
DROP DOMAIN d1, d2;
DROP DATABASE test_database_exists (force);
